  'ops.why.validate':   { es: 'Un daño sin peritar es dinero que nadie ha reclamado.', en: 'Damage not assessed is money nobody has claimed.', fr: 'Un dommage non expertisé, c’est de l’argent que personne ne réclame.', de: 'Ein nicht begutachteter Schaden ist Geld, das niemand fordert.', it: 'Un danno non periziato è denaro che nessuno ha reclamato.', pt: 'Um dano sem peritagem é dinheiro que ninguém reclamou.' },
  'ops.why.incidents':  { es: 'No frenan la operación de mañana, pero se acumulan.', en: 'They don’t block tomorrow’s operation, but they pile up.', fr: 'Elles ne bloquent pas demain, mais elles s’accumulent.', de: 'Sie blockieren morgen nicht, häufen sich aber an.', it: 'Non bloccano il lavoro di domani, ma si accumulano.', pt: 'Não travam a operação de amanhã, mas acumulam-se.' },
