  'ob.titulo':        { es: "Pon en marcha tu flota", en: "Get your fleet running", fr: "Mettez votre flotte en route", de: "Bring deine Flotte zum Laufen", it: "Avvia la tua flotta", pt: "Põe a tua frota a funcionar" },
  'ob.sub':           { es: "Tres pasos y tendrás el control diario funcionando. Puedes hacerlos en cualquier orden.", en: "Three steps and your daily control is running. You can do them in any order.", fr: "Trois étapes et votre suivi quotidien fonctionne. Dans n'importe quel ordre.", de: "Drei Schritte und die tägliche Kontrolle läuft. In beliebiger Reihenfolge.", it: "Tre passi e il controllo quotidiano è attivo. In qualsiasi ordine.", pt: "Três passos e o controlo diário fica a funcionar. Por qualquer ordem." },
