  'ops.why.sinrevisar': { es: 'Sin fotos de salida, un golpe que aparezca a la vuelta no se puede atribuir a nadie.', en: 'Without departure photos, damage found on return cannot be attributed to anyone.', fr: 'Sans photos au départ, un dégât constaté au retour ne peut être attribué à personne.', de: 'Ohne Abfahrtsfotos lässt sich ein Schaden bei der Rückkehr niemandem zuordnen.', it: 'Senza foto alla partenza, un danno trovato al rientro non si può attribuire a nessuno.', pt: 'Sem fotos à saída, um dano encontrado no regresso não pode ser atribuído a ninguém.' },
  'ops.brief.empty': { es: "Todavía no hay flota: empieza por añadir tus furgonetas.", en: "No fleet yet: start by adding your vans.", fr: "Pas encore de flotte : commencez par ajouter vos camionnettes.", de: "Noch keine Flotte: füge zuerst deine Fahrzeuge hinzu.", it: "Ancora nessuna flotta: inizia aggiungendo i tuoi furgoni.", pt: "Ainda não há frota: comece por adicionar as suas carrinhas." },
  'empty.portal.cta': { es: "Abrir el portal del conductor", en: "Open the driver portal", fr: "Ouvrir le portail chauffeur", de: "Fahrerportal öffnen", it: "Apri il portale autista", pt: "Abrir o portal do motorista" },
  'act.empty.tit': { es: "Aquí verás cada inspección según llega", en: "Every inspection shows up here as it arrives", fr: "Chaque inspection apparaît ici dès son arrivée", de: "Hier siehst du jede Inspektion, sobald sie ankommt", it: "Qui vedrai ogni ispezione appena arriva", pt: "Aqui verá cada inspeção assim que chegar" },
  'act.empty.hint': { es: "Las suben tus conductores desde el móvil, con el enlace de su portal. En cuanto llegue la primera, sale aquí con la matrícula y lo que ha visto la IA.", en: "Your drivers upload them from their phone using their portal link. As soon as the first one arrives, it appears here with the plate and what the AI found.", fr: "Vos chauffeurs les envoient depuis leur téléphone avec le lien de leur portail. Dès la première, elle apparaît ici avec la plaque et ce que l'IA a vu.", de: "Deine Fahrer laden sie mit dem Link ihres Portals vom Handy hoch. Sobald die erste ankommt, erscheint sie hier mit Kennzeichen und KI-Befund.", it: "I tuoi autisti le caricano dal telefono con il link del loro portale. Appena arriva la prima, compare qui con la targa e ciò che ha visto l'IA.", pt: "Os seus motoristas enviam-nas do telemóvel com o link do portal. Assim que chegar a primeira, aparece aqui com a matrícula e o que a IA viu." },
  'insp.empty.hint': { es: "Las hacen tus conductores desde el móvil: fotos de la furgoneta y del cuentakilómetros. Comparte con ellos el enlace de su portal para empezar.", en: "Your drivers do them from their phone: photos of the van and the odometer. Share their portal link with them to get started.", fr: "Vos chauffeurs les font depuis leur téléphone : photos de la camionnette et du compteur. Partagez-leur le lien de leur portail pour commencer.", de: "Deine Fahrer machen sie vom Handy aus: Fotos vom Fahrzeug und vom Tacho. Teile ihnen den Link ihres Portals, um loszulegen.", it: "Le fanno i tuoi autisti dal telefono: foto del furgone e del contachilometri. Condividi con loro il link del portale per iniziare.", pt: "Os seus motoristas fazem-nas pelo telemóvel: fotos da carrinha e do conta-quilómetros. Partilhe com eles o link do portal para começar." },
  'rev.empty.tit': { es: "Aquí revisarás lo que la IA ve en las fotos", en: "This is where you review what the AI sees in the photos", fr: "Ici, vous vérifierez ce que l'IA voit sur les photos", de: "Hier prüfst du, was die KI auf den Fotos sieht", it: "Qui controllerai ciò che l'IA vede nelle foto", pt: "Aqui vai rever o que a IA vê nas fotos" },
  'rev.empty.hint': { es: "Cuando tus conductores suban sus inspecciones, la IA busca daños y cierra sola lo que tiene claro. Lo que le deje dudas te llegará aquí.", en: "When your drivers upload their inspections, the AI looks for damage and closes what it is sure about. Anything it is unsure of comes here.", fr: "Quand vos chauffeurs envoient leurs inspections, l'IA cherche les dégâts et clôt seule ce qui est clair. Ce qui la fait douter arrive ici.", de: "Wenn deine Fahrer ihre Inspektionen hochladen, sucht die KI nach Schäden und schließt Eindeutiges selbst ab. Was unklar ist, landet hier.", it: "Quando i tuoi autisti caricano le ispezioni, l'IA cerca i danni e chiude da sola ciò che è chiaro. Ciò che le lascia dubbi arriva qui.", pt: "Quando os seus motoristas enviarem as inspeções, a IA procura danos e fecha sozinha o que é claro. O que lhe deixar dúvidas chega aqui." },
  'pk.ejemplo': { es: "Plano de ejemplo", en: "Sample layout", fr: "Plan d'exemple", de: "Beispielplan", it: "Piantina di esempio", pt: "Planta de exemplo" },
  'pk.ejemplo.hint': { es: "Este plano es de ejemplo, no el de tu centro. Dibuja tus zonas y plazas y, cuando lo guardes, aquí verás qué furgoneta está en cada plaza.", en: "This is a sample layout, not your site's. Draw your zones and bays; once you save it, you will see which van is in each bay.", fr: "Ce plan est un exemple, pas celui de votre site. Dessinez vos zones et places ; une fois enregistré, vous verrez quelle camionnette occupe chaque place.", de: "Dieser Plan ist ein Beispiel, nicht der deiner Standort. Zeichne deine Zonen und Stellplätze; nach dem Speichern siehst du, welches Fahrzeug wo steht.", it: "Questa piantina è di esempio, non quella della tua sede. Disegna zone e posti; una volta salvata, vedrai quale furgone occupa ogni posto.", pt: "Esta planta é um exemplo, não a da sua centro. Desenhe as zonas e os lugares; depois de guardar, verá que carrinha está em cada lugar." },
  'pk.ejemplo.cta': { es: "Dibujar mi aparcamiento", en: "Draw my parking", fr: "Dessiner mon parking", de: "Meinen Parkplatz zeichnen", it: "Disegna il mio parcheggio", pt: "Desenhar o meu parque" },

