  'dr.spare.title':   { es: "¿Lleva rueda de repuesto?", en: "Does it have a spare wheel?", fr: "A-t-il une roue de secours ?", de: "Hat es ein Reserverad?", it: "Ha la ruota di scorta?", pt: "Tem roda sobresselente?" },
  'dr.spare.hint':    { es: "Mira debajo o en el maletero antes de responder. Si no puedes mirar, dilo: es una respuesta válida.", en: "Look underneath or in the boot before answering. If you cannot check, say so: that is a valid answer.", fr: "Regarde dessous ou dans le coffre avant de répondre. Si tu ne peux pas vérifier, dis-le : c'est une réponse valable.", de: "Schau darunter oder im Kofferraum nach, bevor du antwortest. Wenn du nicht nachsehen kannst, sag es: das ist eine gültige Antwort.", it: "Guarda sotto o nel bagagliaio prima di rispondere. Se non puoi controllare, dillo: è una risposta valida.", pt: "Olha por baixo ou na mala antes de responder. Se não puderes verificar, diz-lo: é uma resposta válida." },
  'dr.spare.yes':     { es: "Sí, la lleva", en: "Yes, it has one", fr: "Oui, elle y est", de: "Ja, vorhanden", it: "Sì, c'è", pt: "Sim, tem" },
  'dr.spare.no':      { es: "No la lleva", en: "No, it doesn't", fr: "Non, absente", de: "Nein, fehlt", it: "No, manca", pt: "Não tem" },
  'dr.spare.dunno':   { es: "No he podido mirar", en: "I couldn't check", fr: "Je n'ai pas pu vérifier", de: "Konnte nicht nachsehen", it: "Non ho potuto controllare", pt: "Não consegui verificar" },
  'dr.spare.req':     { es: "Responde si lleva rueda de repuesto", en: "Answer whether it has a spare wheel", fr: "Indique s'il y a une roue de secours", de: "Gib an, ob ein Reserverad vorhanden ist", it: "Indica se ha la ruota di scorta", pt: "Indica se tem roda sobresselente" },
  'dr.revisaResumen': { es: "Revisa el resumen antes de enviar la inspección", en: "Check the summary before sending the inspection", fr: "Vérifiez le résumé avant d'envoyer l'inspection", de: "Prüfe die Zusammenfassung vor dem Senden", it: "Controlla il riepilogo prima di inviare", pt: "Revê o resumo antes de enviar a inspeção" },
  'dr.fotosEnviadas': { es: "Fotos enviadas", en: "Photos sent", fr: "Photos envoyées", de: "Gesendete Fotos", it: "Foto inviate", pt: "Fotos enviadas" },
