  'ff.sugLleva': { es: "Lleva la {p} {v} de sus últimos {d} días", en: "Drove {p} on {v} of their last {d} days", fr: "A conduit le {p} {v} de ses {d} derniers jours", de: "Fuhr {p} an {v} seiner letzten {d} Tage", it: "Ha guidato il {p} {v} dei suoi ultimi {d} giorni", pt: "Levou a {p} {v} dos seus últimos {d} dias" },
  'ff.asignar': { es: "Asignársela", en: "Assign it", fr: "L'attribuer", de: "Zuteilen", it: "Assegnaglielo", pt: "Atribuir-lha" },
  'ff.editar': { es: "Editar", en: "Edit", fr: "Modifier", de: "Bearbeiten", it: "Modifica", pt: "Editar" },
  'ff.listo': { es: "Listo", en: "Done", fr: "Terminé", de: "Fertig", it: "Fatto", pt: "Pronto" },
  'ff.ed.titular': { es: "Tiene preferencia si la comparte", en: "Has priority if shared", fr: "Prioritaire s'il est partagé", de: "Hat Vorrang, wenn geteilt", it: "Ha la precedenza se condiviso", pt: "Tem preferência se a partilhar" },
  'ff.ed.titularAyuda': { es: "Si otro tiene la misma furgoneta y trabajan el mismo día, se la queda él y el otro pasa a su reserva.", en: "If someone else has the same van and they work the same day, this driver keeps it and the other gets their spare.", fr: "Si un autre a le même fourgon et qu'ils travaillent le même jour, il le garde et l'autre prend sa réserve.", de: "Hat ein anderer dasselbe Fahrzeug und beide arbeiten am selben Tag, behält er es und der andere nimmt sein Ersatzfahrzeug.", it: "Se un altro ha lo stesso furgone e lavorano lo stesso giorno, lo tiene lui e l'altro passa alla riserva.", pt: "Se outro tem a mesma carrinha e trabalham no mesmo dia, fica ele com ela e o outro passa à reserva." },
  'ff.ed.comparte': { es: "También es la furgoneta de", en: "Also the van of", fr: "C'est aussi le fourgon de", de: "Ist auch das Fahrzeug von", it: "È anche il furgone di", pt: "Também é a carrinha de" },
  'ff.ed.sinAuto': { es: "Sin furgoneta fija", en: "No fixed van", fr: "Sans fourgon attitré", de: "Kein festes Fahrzeug", it: "Senza furgone fisso", pt: "Sem carrinha fixa" },
  'ff.ed.sinAutoAyuda': { es: "No se le pone furgoneta sola: se le elige cada día a mano entre las libres.", en: "Never gets a van automatically: pick one by hand from the free ones each day.", fr: "Jamais de fourgon automatique : on le choisit chaque jour parmi les libres.", de: "Bekommt nie automatisch eins: täglich von Hand aus den freien wählen.", it: "Non riceve mai un furgone da solo: si sceglie ogni giorno a mano tra i liberi.", pt: "Nunca recebe carrinha sozinha: escolhe-se cada dia à mão entre as livres." },
  'ff.ed.nota': { es: "Nota de responsabilidad", en: "Reliability rating", fr: "Note de fiabilité", de: "Zuverlässigkeitsnote", it: "Voto di affidabilità", pt: "Nota de responsabilidade" },
  'ff.ed.notaAyuda': { es: "Del 1 al 10. Las furgonetas nuevas o recién reparadas van antes a quien tiene más nota.", en: "1 to 10. New or just-repaired vans go first to the highest rated.", fr: "De 1 à 10. Les fourgons neufs ou réparés vont d'abord aux mieux notés.", de: "1 bis 10. Neue oder frisch reparierte Fahrzeuge gehen zuerst an die Bestbewerteten.", it: "Da 1 a 10. I furgoni nuovi o appena riparati vanno prima a chi ha il voto più alto.", pt: "De 1 a 10. As carrinhas novas ou acabadas de reparar vão primeiro a quem tem mais nota." },
