  'ff.dlg.propResumen': { es: "Propone furgoneta para {n} conductores. Desmarca lo que no te convenza.", en: "Suggests a van for {n} drivers. Untick anything you don't like.", fr: "Propose un fourgon pour {n} chauffeurs. Décochez ce qui ne convient pas.", de: "Schlägt für {n} Fahrer ein Fahrzeug vor. Entferne, was nicht passt.", it: "Propone un furgone per {n} autisti. Togli la spunta a ciò che non ti convince.", pt: "Propõe carrinha para {n} motoristas. Desmarca o que não te convencer." },
